93	func runReplay(args []string) {
94		versionID := ""
95		rest := args
96		if len(rest) >= 1 && strings.HasPrefix(rest[0], "--version=") {
97			versionID = strings.TrimPrefix(rest[0], "--version=")
98			rest = rest[1:]
99		} else if len(rest) >= 2 && rest[0] == "--version" {
100			versionID = rest[1]
101			rest = rest[2:]
102		}
103		if len(rest) != 2 {
104			fmt.Fprintln(os.Stderr, "usage: mevwatch replay [--version <id>] <input-file> <archive-dir>")
105			os.Exit(2)
106		}
107		var reports []mevwatch.Report
108		var err error
109		if versionID != "" {
110			reports, err = mevwatch.ReplayFileWithVersion(rest[0], rest[1], versionID)
111		} else {
112			reports, err = mevwatch.ReplayFile(rest[0], rest[1])
113		}
114		if err != nil {
115			fmt.Fprintf(os.Stderr, "replay: %v\n", err)
116			os.Exit(1)
117		}
118		for _, report := range reports {
119			writeJSON(report)
120		}
121	}
