123	func runRules(args []string) {
124		if len(args) < 1 {
125			fmt.Fprintln(os.Stderr, "usage: mevwatch rules <list|show|register|enable> ...")
126			os.Exit(2)
127		}
128		switch args[0] {
129		case "list":
130			if len(args) != 2 {
131				fmt.Fprintln(os.Stderr, "usage: mevwatch rules list <archive-dir>")
132				os.Exit(2)
133			}
134			versions, enabled, err := mevwatch.ListVersions(args[1])
135			if err != nil {
136				fmt.Fprintf(os.Stderr, "rules list: %v\n", err)
137				os.Exit(1)
138			}
139			writeJSON(struct {
140				Enabled  string                 `json:"enabled"`
141				Versions []mevwatch.RuleVersion `json:"versions"`
142			}{Enabled: enabled, Versions: versions})
143		case "show":
144			if len(args) != 3 {
145				fmt.Fprintln(os.Stderr, "usage: mevwatch rules show <archive-dir> <version-id>")
146				os.Exit(2)
147			}
148			version, err := mevwatch.GetVersion(args[1], args[2])
149			if err != nil {
150				fmt.Fprintf(os.Stderr, "rules show: %v\n", err)
151				os.Exit(1)
152			}
153			writeJSON(version)
154		case "register":
155			if len(args) != 3 {
156				fmt.Fprintln(os.Stderr, "usage: mevwatch rules register <archive-dir> <spec-file>")
157				os.Exit(2)
158			}
159			var raw []byte
160			var err error
161			if args[2] == "-" {
162				raw, err = io.ReadAll(os.Stdin)
163			} else {
164				raw, err = os.ReadFile(args[2])
165			}
166			if err != nil {
167				fmt.Fprintf(os.Stderr, "rules register: %v\n", err)
168				os.Exit(1)
169			}
170			version, created, err := mevwatch.RegisterVersion(args[1], raw)
171			if err != nil {
172				fmt.Fprintf(os.Stderr, "rules register: %v\n", err)
173				os.Exit(1)
174			}
175			writeJSON(struct {
176				Created bool                 `json:"created"`
177				Version mevwatch.RuleVersion `json:"version"`
178			}{Created: created, Version: version})
179		case "enable":
180			if len(args) != 3 {
181				fmt.Fprintln(os.Stderr, "usage: mevwatch rules enable <archive-dir> <version-id>")
182				os.Exit(2)
183			}
184			version, err := mevwatch.EnableVersion(args[1], args[2])
185			if err != nil {
186				fmt.Fprintf(os.Stderr, "rules enable: %v\n", err)
187				os.Exit(1)
188			}
189			writeJSON(version)
190		default:
191			fmt.Fprintf(os.Stderr, "unknown rules subcommand %q\n", args[0])
192			usage()
193			os.Exit(2)
194		}
195	}
