404	func runDemo() {
405		swaps := []mevwatch.Swap{
406			{TxHash: "0xfront", Pool: "pool-1", Trader: "bot-a", In: 500, Out: 480, GasPrice: 90, Index: 0},
407			{TxHash: "0xvictim", Pool: "pool-1", Trader: "user-1", In: 200, Out: 188, GasPrice: 12, Index: 1},
408			{TxHash: "0xback", Pool: "pool-1", Trader: "bot-a", In: 480, Out: 505, GasPrice: 80, Index: 2},
409		}
410		findings := mevwatch.Detect(swaps, "0xvictim")
411		for _, finding := range mevwatch.Rank(findings) {
412			fmt.Printf("tx=%s kind=%s severity=%d evidence=%v\n", finding.TxHash, finding.Kind, finding.Severity, finding.Evidence)
413		}
414		fmt.Printf("swaps=%d findings=%d\n", len(swaps), len(findings))
415	}
