3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"io"
9		"os"
10		"sort"
11		"syscall"
12	)
13	
14	// BuiltinVersionID identifies the built-in rule version, which reproduces
15	// the original fixed rules. It is always available, its parameters are
16	// queryable, and it cannot be overridden.
17	const BuiltinVersionID = "builtin"
18	
19	// ErrUnknownVersion reports a reference to a rule version that was never
20	// registered in the archive.
21	var ErrUnknownVersion = errors.New("unknown version")
22	
23	// ErrVersionConflict reports a re-registration of an existing version ID
24	// with different parameters.
25	var ErrVersionConflict = errors.New("version already registered with different parameters")
26	
27	// SandwichRule configures the sandwich rule: whether it runs and the
28	// severity of its conclusions.
29	type SandwichRule struct {
30		Enabled  bool `json:"enabled"`
31		Severity int  `json:"severity"`
32	}
33	
34	// DisplacementRule configures the displacement rule. A victim is flagged
35	// only when the previous swap's GasPrice strictly exceeds Multiplier times
36	// the victim's.
37	type DisplacementRule struct {
38		Enabled    bool `json:"enabled"`
39		Severity   int  `json:"severity"`
40		Multiplier int  `json:"multiplier"`
41	}
42	
43	// RuleSet is the complete declaration of both detection rules. Every
44	// version must declare both rules in full.
45	type RuleSet struct {
46		Sandwich     SandwichRule     `json:"sandwich"`
47		Displacement DisplacementRule `json:"displacement"`
48	}
49	
50	// RuleVersion is a named, immutable set of rule parameters.
51	type RuleVersion struct {
52		ID    string  `json:"id"`
53		Rules RuleSet `json:"rules"`
54	}
55	
56	// BuiltinVersion returns the version representing the original fixed
57	// rules: sandwich severity 3, displacement severity 2 with multiplier 2.
58	func BuiltinVersion() RuleVersion {
59		return RuleVersion{
60			ID: BuiltinVersionID,
61			Rules: RuleSet{
62				Sandwich:     SandwichRule{Enabled: true, Severity: 3},
63				Displacement: DisplacementRule{Enabled: true, Severity: 2, Multiplier: 2},
64			},
65		}
66	}
67	
68	// toggleSpec and displacementSpec mirror the registration JSON. Pointers
69	// distinguish a missing field from an explicit zero value, and the decoder
70	// rejects unknown fields (including unknown rule names).
71	type toggleSpec struct {
72		Enabled  *bool `json:"enabled"`
73		Severity *int  `json:"severity"`
74	}
75	
76	type displacementSpec struct {
77		Enabled    *bool `json:"enabled"`
78		Severity   *int  `json:"severity"`
79		Multiplier *int  `json:"multiplier"`
80	}
81	
82	type versionSpec struct {
83		ID    *string `json:"id"`
84		Rules *struct {
85			Sandwich     *toggleSpec       `json:"sandwich"`
86			Displacement *displacementSpec `json:"displacement"`
87		} `json:"rules"`
88	}
89	
90	func parseEnabled(name string, v *bool) (bool, error) {
91		if v == nil {
92			return false, fmt.Errorf("rules.%s.enabled is required (boolean)", name)
93		}
94		return *v, nil
95	}
96	
97	func parseSeverity(name string, v *int) (int, error) {
98		if v == nil {
99			return 0, fmt.Errorf("rules.%s.severity is required (integer 1-5)", name)
100		}
101		if *v < 1 || *v > 5 {
102			return 0, fmt.Errorf("rules.%s.severity must be between 1 and 5, got %d", name, *v)
103		}
104		return *v, nil
105	}
106	
107	// ErrDuplicateField reports a JSON object in a registration spec that
108	// names the same field twice. Field names are compared the way JSON
109	// decoding matches struct fields, so two spellings the decoder folds
110	// together — differing only in case, like "severity" and "Severity", or
111	// using a compatibility character, like "ſeverity" (U+017F for s) — are
112	// also duplicates.
113	var ErrDuplicateField = errors.New("duplicate field in version spec")
114	
115	// ErrTrailingData reports non-whitespace content after the single JSON
116	// object that makes up a registration spec: a second object, another
117	// JSON value, an unmatched bracket or any other character.
118	var ErrTrailingData = errors.New("unexpected trailing data after version spec")
119	
120	// versionScanPolicy validates the shape of a rule version document with
121	// the shared scanner while keeping version-spec wording and sentinel
122	// errors.
123	var versionScanPolicy = specPolicy{
124		topObject:          "version spec",
125		known:              versionFields,
126		nested:             versionNestedTables,
127		rejectExactUnknown: true,
128		firstTokenError: func(err error) error {
129			if errors.Is(err, io.EOF) {
130				return errors.New("version spec must be a JSON object, got empty input")
131			}
132			return fmt.Errorf("invalid version spec: %w", err)
133		},
134		nonObject: func(tok json.Token) error {
135			if tok == nil {
136				return errors.New("version spec must be a JSON object, got null")
137			}
138			if d, ok := tok.(json.Delim); ok && d == '[' {
139				return errors.New("version spec must be a single JSON object, got array")
140			}
141			return fmt.Errorf("version spec must be a single JSON object, got %s", jsonTokenName(tok))
142		},
143		wrap: func(err error) error {
144			return fmt.Errorf("invalid version spec: %w", err)
145		},
146		duplicate: func(obj, field, first, _ string) error {
147			return fmt.Errorf("%w: %s field %q (also written %q)", ErrDuplicateField, obj, field, first)
148		},
149		trailing: versionTrailingData,
150	}
151	
152	// validateSpecStructure proves raw contains exactly one JSON object with
153	// no repeated fields anywhere in it, and nothing but whitespace around
154	// it. Keys are matched against the known fields of the version, rules,
155	// sandwich and displacement objects with the decoder's own field-name
156	// folding: "SEVERITY", "severity" and "ſeverity" (U+017F for s) all point
157	// at the same field and cannot share one object. Escaped key spellings
158	// are decoded before comparison, so "severity" cannot evade it.
159	func validateSpecStructure(raw []byte) error {
160		return scanJSONObject(raw, versionScanPolicy)
161	}
162	
163	// versionTrailingData names the first non-whitespace byte after the
164	// closed object, so an unmatched '}' or ']' is reported directly rather
165	// than as a syntax error; only whitespace may follow the object.
166	func versionTrailingData(raw []byte, offset int) error {
167		rest := bytes.TrimLeft(raw[offset:], " \t\n\r")
168		if len(rest) > 0 {
169			return fmt.Errorf("%w: %s after closing object", ErrTrailingData, trailingTokenName(rest[0]))
170		}
171		return nil
172	}
173	
174	var (
175		versionFields       = fieldTable("id", "rules")
176		rulesFields         = fieldTable("sandwich", "displacement")
177		sandwichFields      = fieldTable("enabled", "severity")
178		displacementFields  = fieldTable("enabled", "severity", "multiplier")
179		versionNestedTables = map[string]nestedObjectSpec{
180			"rules":        {rulesFields, "rules object"},
181			"sandwich":     {sandwichFields, "rules.sandwich"},
182			"displacement": {displacementFields, "rules.displacement"},
183		}
184	)
185	
186	// ParseRuleVersion validates a registration document. It must contain
187	// exactly one complete JSON object (leading and trailing whitespace
188	// allowed): a second object or value, an unmatched bracket or any other
189	// trailing character fails, and empty input, arrays and null are not
190	// specs. Duplicate fields are rejected at the top level, in rules and in
191	// each rule's parameters, including any spellings the decoder folds onto
192	// the same known field (case variants, U+017F for s, and the like). Missing fields, wrong types, out-of-range values and unknown
193	// rules or fields all fail with a reason.
194	func ParseRuleVersion(raw []byte) (RuleVersion, error) {
195		if err := validateSpecStructure(raw); err != nil {
196			return RuleVersion{}, err
197		}
198		var spec versionSpec
199		dec := json.NewDecoder(bytes.NewReader(raw))
200		dec.DisallowUnknownFields()
201		if err := dec.Decode(&spec); err != nil {
202			return RuleVersion{}, fmt.Errorf("invalid version spec: %w", err)
203		}
204		if spec.ID == nil || *spec.ID == "" {
205			return RuleVersion{}, errors.New("id must be a non-empty string")
206		}
207		if spec.Rules == nil {
208			return RuleVersion{}, errors.New("rules must declare sandwich and displacement")
209		}
210		if spec.Rules.Sandwich == nil {
211			return RuleVersion{}, errors.New("rules.sandwich is required")
212		}
213		if spec.Rules.Displacement == nil {
214			return RuleVersion{}, errors.New("rules.displacement is required")
215		}
216		sandwichOn, err := parseEnabled("sandwich", spec.Rules.Sandwich.Enabled)
217		if err != nil {
218			return RuleVersion{}, err
219		}
220		sandwichSev, err := parseSeverity("sandwich", spec.Rules.Sandwich.Severity)
221		if err != nil {
222			return RuleVersion{}, err
223		}
224		dispOn, err := parseEnabled("displacement", spec.Rules.Displacement.Enabled)
225		if err != nil {
226			return RuleVersion{}, err
227		}
228		dispSev, err := parseSeverity("displacement", spec.Rules.Displacement.Severity)
229		if err != nil {
230			return RuleVersion{}, err
231		}
232		mult := spec.Rules.Displacement.Multiplier
233		if mult == nil {
234			return RuleVersion{}, errors.New("rules.displacement.multiplier is required (integer 2-100)")
235		}
236		if *mult < 2 || *mult > 100 {
237			return RuleVersion{}, fmt.Errorf("rules.displacement.multiplier must be between 2 and 100, got %d", *mult)
238		}
239		return RuleVersion{
240			ID: *spec.ID,
241			Rules: RuleSet{
242				Sandwich:     SandwichRule{Enabled: sandwichOn, Severity: sandwichSev},
243				Displacement: DisplacementRule{Enabled: dispOn, Severity: dispSev, Multiplier: *mult},
244			},
245		}, nil
246	}
247	
248	// findVersion resolves id against the built-in version and the archive's
249	// registered versions.
250	func findVersion(data archiveData, id string) (RuleVersion, error) {
251		if id == BuiltinVersionID {
252			return BuiltinVersion(), nil
253		}
254		for _, v := range data.Versions {
255			if v.ID == id {
256				return v, nil
257			}
258		}
259		return RuleVersion{}, fmt.Errorf("%w: %s", ErrUnknownVersion, id)
260	}
261	
262	// enabledVersion resolves the archive's currently enabled version. Archives
263	// written before rule versions existed have no marker and run the built-in
264	// rules.
265	func (d archiveData) enabledVersion() (RuleVersion, error) {
266		if d.EnabledVersion == "" {
267			return BuiltinVersion(), nil
268		}
269		return findVersion(d, d.EnabledVersion)
270	}
271	
272	// RegisterVersion validates raw as a rule version spec and stores it in the
273	// archive at dir. Re-registering the same ID with identical parameters
274	// succeeds without adding a version (created is false); the same ID with
275	// different parameters is rejected. The built-in version ID is reserved.
276	// Any failure leaves the archive untouched.
277	func RegisterVersion(dir string, raw []byte) (v RuleVersion, created bool, err error) {
278		v, err = ParseRuleVersion(raw)
279		if err != nil {
280			return RuleVersion{}, false, err
281		}
282		if v.ID == BuiltinVersionID {
283			return RuleVersion{}, false, fmt.Errorf("version id %q is reserved for the built-in rules", BuiltinVersionID)
284		}
285		if err := os.MkdirAll(dir, 0o755); err != nil {
286			return RuleVersion{}, false, err
287		}
288		lock, err := lockArchive(dir, syscall.LOCK_EX|syscall.LOCK_NB)
289		if err != nil {
290			return RuleVersion{}, false, err
291		}
292		defer lock.Close()
293	
294		data, err := readArchive(dir)
295		if err != nil {
296			return RuleVersion{}, false, err
297		}
298		for _, existing := range data.Versions {
299			if existing.ID == v.ID {
300				if existing.Rules == v.Rules {
301					return existing, false, nil
302				}
303				return RuleVersion{}, false, fmt.Errorf("%w: %s", ErrVersionConflict, v.ID)
304			}
305		}
306		data.Versions = append(data.Versions, v)
307		if err := writeArchiveAtomic(dir, data); err != nil {
308			return RuleVersion{}, false, err
309		}
310		return v, true, nil
311	}
312	
313	// EnableVersion makes id the archive's active version for later replays.
314	// Enabling an unknown version fails and leaves the current enabled version
315	// unchanged.
316	func EnableVersion(dir, id string) (RuleVersion, error) {
317		if id == "" {
318			return RuleVersion{}, errors.New("version id must not be empty")
319		}
320		if err := os.MkdirAll(dir, 0o755); err != nil {
321			return RuleVersion{}, err
322		}
323		lock, err := lockArchive(dir, syscall.LOCK_EX|syscall.LOCK_NB)
324		if err != nil {
325			return RuleVersion{}, err
326		}
327		defer lock.Close()
328	
329		data, err := readArchive(dir)
330		if err != nil {
331			return RuleVersion{}, err
332		}
333		v, err := findVersion(data, id)
334		if err != nil {
335			return RuleVersion{}, err
336		}
337		if data.EnabledVersion == id {
338			return v, nil
339		}
340		data.EnabledVersion = id
341		if err := writeArchiveAtomic(dir, data); err != nil {
342			return RuleVersion{}, err
343		}
344		return v, nil
345	}
346	
347	// ListVersions returns the built-in version plus every version registered
348	// in the archive, along with the currently enabled version ID.
349	func ListVersions(dir string) (versions []RuleVersion, enabled string, err error) {
350		if _, serr := os.Stat(dir); errors.Is(serr, os.ErrNotExist) {
351			return []RuleVersion{BuiltinVersion()}, BuiltinVersionID, nil
352		}
353		lock, err := lockArchive(dir, syscall.LOCK_SH)
354		if err != nil {
355			return nil, "", err
356		}
357		defer lock.Close()
358	
359		data, err := readArchive(dir)
360		if err != nil {
361			return nil, "", err
362		}
363		versions = append([]RuleVersion{BuiltinVersion()}, data.Versions...)
364		enabled = data.EnabledVersion
365		if enabled == "" {
366			enabled = BuiltinVersionID
367		}
368		return versions, enabled, nil
369	}
370	
371	// GetVersion returns one version's full parameters by ID.
372	func GetVersion(dir, id string) (RuleVersion, error) {
373		if id == BuiltinVersionID {
374			return BuiltinVersion(), nil
375		}
376		if _, serr := os.Stat(dir); errors.Is(serr, os.ErrNotExist) {
377			return RuleVersion{}, fmt.Errorf("%w: %s", ErrUnknownVersion, id)
378		}
379		lock, err := lockArchive(dir, syscall.LOCK_SH)
380		if err != nil {
381			return RuleVersion{}, err
382		}
383		defer lock.Close()
384	
385		data, err := readArchive(dir)
386		if err != nil {
387			return RuleVersion{}, err
388		}
389		return findVersion(data, id)
390	}
391	
392	// FindingChange pairs the archived and compared conclusions for one
393	// transaction whose kind or severity differs between the two versions.
394	type FindingChange struct {
395		TxHash   string        `json:"txHash"`
396		Original ReportFinding `json:"original"`
397		Compared ReportFinding `json:"compared"`
398	}
399	
400	// CompareResult is the outcome of re-judging one archived block under a
401	// different rule version. It carries both versions' parameters, both full
402	// conclusion sets, the raw swap evidence, and the per-transaction diff.
403	type CompareResult struct {
404		ChainID          string          `json:"chainId"`
405		BlockHash        string          `json:"blockHash"`
406		BlockNumber      int64           `json:"blockNumber"`
407		OriginalVersion  RuleVersion     `json:"originalVersion"`
408		ComparedVersion  RuleVersion     `json:"comparedVersion"`
409		OriginalFindings []ReportFinding `json:"originalFindings"`
410		ComparedFindings []ReportFinding `json:"comparedFindings"`
411		Swaps            []Swap          `json:"swaps"`
412		Added            []ReportFinding `json:"added"`
413		Removed          []ReportFinding `json:"removed"`
414		Changed          []FindingChange `json:"changed"`
415	}
416	
417	// Compare re-runs detection for one archived block under the given
418	// registered version and diffs the conclusions against the archived
419	// report. It only reads the archive: the original input file is not
420	// needed, and neither the archived report nor the enabled version is
421	// modified.
422	func Compare(dir, chainID, blockHash, versionID string) (CompareResult, error) {
423		if _, err := os.Stat(dir); err != nil {
424			if errors.Is(err, os.ErrNotExist) {
425				return CompareResult{}, ErrUnknownBlock
426			}
427			return CompareResult{}, err
428		}
429		lock, err := lockArchive(dir, syscall.LOCK_SH)
430		if err != nil {
431			return CompareResult{}, err
432		}
433		defer lock.Close()
434	
435		data, err := readArchive(dir)
436		if err != nil {
437			return CompareResult{}, err
438		}
439		var rec *record
440		for i := range data.Records {
441			if data.Records[i].ChainID == chainID && data.Records[i].BlockHash == blockHash {
442				rec = &data.Records[i]
443				break
444			}
445		}
446		if rec == nil {
447			return CompareResult{}, ErrUnknownBlock
448		}
449		compared, err := findVersion(data, versionID)
450		if err != nil {
451			return CompareResult{}, err
452		}
453	
454		original := rec.Findings
455		if original == nil {
456			original = []ReportFinding{}
457		}
458		rejudged := DetectBlockWithRules(rec.Swaps, compared.Rules)
459		swaps := rec.Swaps
460		if swaps == nil {
461			swaps = []Swap{}
462		}
463	
464		origByTx := make(map[string]ReportFinding, len(original))
465		for _, f := range original {
466			origByTx[f.TxHash] = f
467		}
468		compByTx := make(map[string]ReportFinding, len(rejudged))
469		for _, f := range rejudged {
470			compByTx[f.TxHash] = f
471		}
472		added := []ReportFinding{}
473		removed := []ReportFinding{}
474		changed := []FindingChange{}
475		for _, f := range rejudged {
476			if o, ok := origByTx[f.TxHash]; ok {
477				// A transaction present on both sides with a different kind or
478				// severity is a change, never an add plus a remove.
479				if o.Kind != f.Kind || o.Severity != f.Severity {
480					changed = append(changed, FindingChange{TxHash: f.TxHash, Original: o, Compared: f})
481				}
482			} else {
483				added = append(added, f)
484			}
485		}
486		for _, f := range original {
487			if _, ok := compByTx[f.TxHash]; !ok {
488				removed = append(removed, f)
489			}
490		}
491		byTx := func(fs []ReportFinding) {
492			sort.Slice(fs, func(i, j int) bool { return fs[i].TxHash < fs[j].TxHash })
493		}
494		byTx(added)
495		byTx(removed)
496		sort.Slice(changed, func(i, j int) bool { return changed[i].TxHash < changed[j].TxHash })
497	
498		return CompareResult{
499			ChainID:          rec.ChainID,
500			BlockHash:        rec.BlockHash,
501			BlockNumber:      rec.BlockNumber,
502			OriginalVersion:  rec.ruleVersion(),
503			ComparedVersion:  compared,
504			OriginalFindings: original,
505			ComparedFindings: rejudged,
506			Swaps:            swaps,
507			Added:            added,
508			Removed:          removed,
509			Changed:          changed,
510		}, nil
511	}
512

