	if r.Version != BuiltinVersion() {
		t.Fatalf("legacy record version = %+v, want builtin", r.Version)
	}
	if len(r.Findings) != 1 || r.Findings[0].Kind != "sandwich" || r.Findings[0].Severity != 3 ||
